ALTER TABLE public.seo_pages ADD CONSTRAINT seo_canonical_self CHECK(canonical_url='' OR canonical_url='https://goldcenterstr.com'||CASE WHEN url_slug='' THEN path ELSE regexp_replace(path,'[^/]+$',url_slug) END);
ALTER TABLE public.seo_pages ADD CONSTRAINT seo_slug_only_entities CHECK(entity_type<>'page' OR url_slug='');
ALTER TABLE public.seo_redirects ADD CONSTRAINT seo_redirect_safe_decoded CHECK(source_path !~* '%(2f|5c|3f|23|2e)' AND target_path !~* '%(2f|5c|3f|23|2e)' AND source_path !~ '/\.\.?(/|$)' AND target_path !~ '/\.\.?(/|$)');
CREATE POLICY seo_article_management ON public.posts FOR ALL TO authenticated USING(public.has_dashboard_permission(auth.uid(),'seo')) WITH CHECK(public.has_dashboard_permission(auth.uid(),'seo'));
ALTER POLICY "read published" ON public.posts USING((published AND (publish_at IS NULL OR publish_at<=now())) OR public.has_role(auth.uid(),'admin'));
ALTER POLICY "Visitors read published posts" ON public.posts USING(published AND (publish_at IS NULL OR publish_at<=now()));
CREATE OR REPLACE FUNCTION public.register_seo_content() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE base text; new_path text; old_path text; BEGIN base:=CASE TG_TABLE_NAME WHEN 'product_groups' THEN '/groups/' WHEN 'product_categories' THEN '/categories/' ELSE '/'||TG_TABLE_NAME||'/' END; IF TG_OP='DELETE' THEN DELETE FROM public.seo_pages WHERE entity_type=TG_TABLE_NAME AND entity_id=OLD.id::text; RETURN OLD; END IF; new_path:=base||CASE WHEN TG_TABLE_NAME='posts' THEN to_jsonb(NEW)->>'slug' ELSE NEW.id::text END; IF TG_OP='UPDATE' AND TG_TABLE_NAME='posts' AND to_jsonb(NEW)->>'slug' IS DISTINCT FROM to_jsonb(OLD)->>'slug' THEN old_path:=base||(to_jsonb(OLD)->>'slug'); UPDATE public.seo_pages SET path=new_path,canonical_url='',url_slug='',updated_at=now() WHERE path=old_path AND entity_type='posts'; INSERT INTO public.seo_redirects(source_path,target_path) VALUES(old_path,new_path) ON CONFLICT(source_path) DO UPDATE SET target_path=excluded.target_path,active=true; END IF; INSERT INTO public.seo_pages(path,entity_type,entity_id) VALUES(new_path,TG_TABLE_NAME,NEW.id::text) ON CONFLICT(path) DO UPDATE SET updated_at=now(); RETURN NEW; END $$;
ALTER TABLE public.seo_keywords DROP CONSTRAINT seo_keywords_page_path_fkey;
ALTER TABLE public.seo_keywords ADD CONSTRAINT seo_keywords_page_path_fkey FOREIGN KEY(page_path) REFERENCES public.seo_pages(path) ON UPDATE CASCADE ON DELETE CASCADE;
CREATE OR REPLACE FUNCTION public.guard_seo_redirect() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE current_path text; hop integer; BEGIN PERFORM pg_advisory_xact_lock(762302); IF NEW.source_path ~ '^/(admin|auth|api|account|cart|favorites|reset-password|set-password)(/|$)' OR NEW.target_path ~ '^/(admin|auth|api|account|cart|favorites|reset-password|set-password)(/|$)' THEN RAISE EXCEPTION 'Private destinations not allowed'; END IF; IF NEW.active THEN current_path:=NEW.target_path; FOR hop IN 1..32 LOOP IF current_path=NEW.source_path THEN RAISE EXCEPTION 'Redirect cycle'; END IF; SELECT target_path INTO current_path FROM public.seo_redirects WHERE source_path=current_path AND active AND source_path<>NEW.source_path; IF NOT FOUND THEN RETURN NEW; END IF; END LOOP; RAISE EXCEPTION 'Redirect chain too long'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.seo_page_changed() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE base text; old_url text; new_url text; BEGIN NEW.updated_at:=now(); IF NEW.url_slug IS DISTINCT FROM OLD.url_slug AND NEW.entity_type<>'page' THEN base:=regexp_replace(NEW.path,'[^/]+$',''); old_url:=CASE WHEN OLD.url_slug='' THEN OLD.path ELSE base||OLD.url_slug END; new_url:=CASE WHEN NEW.url_slug='' THEN NEW.path ELSE base||NEW.url_slug END; NEW.canonical_url:=''; DELETE FROM public.seo_redirects WHERE source_path=new_url; INSERT INTO public.seo_redirects(source_path,target_path) VALUES(old_url,new_url) ON CONFLICT(source_path) DO UPDATE SET target_path=excluded.target_path,active=true; UPDATE public.seo_redirects SET target_path=new_url WHERE target_path=old_url AND source_path<>old_url; END IF; RETURN NEW; END $$;